(function() {
  'use strict';

  const api = window.CardSpoke.utils;

  CardSpoke_MODS.register('collaboration-hub-expansion', {
    meta: {
      name: 'Collaboration Hub Expansion',
      type: 'Expansion',
      version: '1.0.0',
      creator: 'CardSpoke',
      description: 'Full collaboration suite with comments, mentions, activity feed, and card sharing'
    },

    STORAGE_KEY: 'collaboration-hub-data',
    collaborationHub: null,
    activityFeed: [],
    comments: {},
    mentions: {},
    currentUser: null,

    onAppInit(ctx) {
      ctx.logger.log('Collaboration Hub Expansion initialized');
      this.initializeUser();
      this.loadCollaborationData();
      this.createCollaborationHub(ctx);
      this.addKeyboardShortcuts(ctx);
    },

    initializeUser() {
      // Get or create user profile
      let user = localStorage.getItem('collab-user-profile');
      if (!user) {
        const username = prompt('Enter your username for collaboration:') || 'Anonymous';
        this.currentUser = {
          id: this.generateId(),
          username: username,
          createdAt: Date.now()
        };
        localStorage.setItem('collab-user-profile', JSON.stringify(this.currentUser));
      } else {
        this.currentUser = JSON.parse(user);
      }
    },

    loadCollaborationData() {
      try {
        const saved = localStorage.getItem(this.STORAGE_KEY);
        if (saved) {
          const data = JSON.parse(saved);
          this.activityFeed = data.activityFeed || [];
          this.comments = data.comments || {};
          this.mentions = data.mentions || {};
        }
      } catch (err) {
        console.error('Failed to load collaboration data:', err);
      }
    },

    saveCollaborationData() {
      try {
        localStorage.setItem(this.STORAGE_KEY, JSON.stringify({
          activityFeed: this.activityFeed,
          comments: this.comments,
          mentions: this.mentions
        }));
      } catch (err) {
        console.error('Failed to save collaboration data:', err);
      }
    },

    createCollaborationHub(ctx) {
      this.collaborationHub = document.createElement('div');
      this.collaborationHub.id = 'collaboration-hub';
      this.collaborationHub.innerHTML = `
        <div class="collab-hub-header">
          <span>👥 Collaboration Hub</span>
          <div class="collab-user-badge">
            <span class="user-avatar">👤</span>
            <span class="user-name">${this.currentUser.username}</span>
          </div>
          <button class="collab-hub-minimize">−</button>
        </div>
        <div class="collab-hub-body">
          <div class="collab-tabs">
            <button class="collab-tab active" data-tab="activity">📊 Activity</button>
            <button class="collab-tab" data-tab="comments">💬 Comments</button>
            <button class="collab-tab" data-tab="mentions">@ Mentions</button>
            <button class="collab-tab" data-tab="share">🔗 Share</button>
          </div>

          <div class="collab-tab-content" id="collab-activity">
            <div class="activity-feed">
              <div class="empty-state">No activity yet</div>
            </div>
          </div>

          <div class="collab-tab-content" id="collab-comments" style="display: none;">
            <div class="comments-list">
              <div class="empty-state">No comments yet</div>
            </div>
            <div class="comment-composer">
              <textarea class="comment-input" placeholder="Add a comment..."></textarea>
              <button class="add-comment-btn">Post Comment</button>
            </div>
          </div>

          <div class="collab-tab-content" id="collab-mentions" style="display: none;">
            <div class="mentions-list">
              <div class="empty-state">No mentions yet. Use @username to mention someone.</div>
            </div>
          </div>

          <div class="collab-tab-content" id="collab-share" style="display: none;">
            <div class="share-section">
              <h4>Share Current Card</h4>
              <div class="share-link-wrapper">
                <input type="text" class="share-link" readonly>
                <button class="copy-link-btn">📋 Copy</button>
              </div>
              <div class="share-options">
                <h5>Share via:</h5>
                <div class="share-buttons">
                  <button class="share-email">📧 Email</button>
                  <button class="share-json">💾 Export JSON</button>
                  <button class="share-qr">📱 QR Code</button>
                </div>
              </div>
              <div class="collaboration-stats">
                <h4>Statistics</h4>
                <div>Total Comments: <span id="total-comments">0</span></div>
                <div>Active Collaborators: <span id="active-collaborators">1</span></div>
                <div>Activity Events: <span id="activity-count">0</span></div>
              </div>
            </div>
          </div>
        </div>
      `;

      document.body.appendChild(this.collaborationHub);
      this.attachHubListeners(ctx);
      this.updateActivityFeed();
      this.updateStats();
    },

    attachHubListeners(ctx) {
      // Tab switching
      const tabs = this.collaborationHub.querySelectorAll('.collab-tab');
      tabs.forEach(tab => {
        tab.addEventListener('click', () => {
          const tabName = tab.dataset.tab;
          this.switchTab(tabName);
        });
      });

      // Minimize
      const minimizeBtn = this.collaborationHub.querySelector('.collab-hub-minimize');
      minimizeBtn.addEventListener('click', () => {
        this.collaborationHub.classList.toggle('minimized');
      });

      // Add comment
      const addCommentBtn = this.collaborationHub.querySelector('.add-comment-btn');
      addCommentBtn.addEventListener('click', () => this.addComment(ctx));

      // Share buttons
      const copyLinkBtn = this.collaborationHub.querySelector('.copy-link-btn');
      copyLinkBtn.addEventListener('click', () => this.copyShareLink(ctx));

      const shareEmailBtn = this.collaborationHub.querySelector('.share-email');
      shareEmailBtn.addEventListener('click', () => this.shareViaEmail(ctx));

      const shareJsonBtn = this.collaborationHub.querySelector('.share-json');
      shareJsonBtn.addEventListener('click', () => this.shareAsJson(ctx));

      const shareQrBtn = this.collaborationHub.querySelector('.share-qr');
      shareQrBtn.addEventListener('click', () => this.generateQRCode(ctx));
    },

    addKeyboardShortcuts(ctx) {
      this.keyHandler = (e) => {
        // Ctrl+Shift+C: Toggle collaboration hub
        if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key === 'C') {
          e.preventDefault();
          this.collaborationHub.classList.toggle('minimized');
        }
      };
      document.addEventListener('keydown', this.keyHandler);
    },

    switchTab(tabName) {
      // Update tab buttons
      const tabs = this.collaborationHub.querySelectorAll('.collab-tab');
      tabs.forEach(tab => {
        tab.classList.toggle('active', tab.dataset.tab === tabName);
      });

      // Update tab content
      const contents = this.collaborationHub.querySelectorAll('.collab-tab-content');
      contents.forEach(content => {
        content.style.display = 'none';
      });

      const activeContent = this.collaborationHub.querySelector(`#collab-${tabName}`);
      if (activeContent) {
        activeContent.style.display = 'block';
      }

      // Update share link when switching to share tab
      if (tabName === 'share') {
        this.updateShareLink();
      }
    },

    addActivity(type, cardId, details) {
      const activity = {
        id: this.generateId(),
        type: type,
        cardId: cardId,
        details: details,
        user: this.currentUser.username,
        timestamp: Date.now()
      };

      this.activityFeed.unshift(activity);

      // Keep only last 100 activities
      if (this.activityFeed.length > 100) {
        this.activityFeed = this.activityFeed.slice(0, 100);
      }

      this.saveCollaborationData();
      this.updateActivityFeed();
    },

    updateActivityFeed() {
      const feedElement = this.collaborationHub.querySelector('.activity-feed');
      if (!feedElement) return;

      if (this.activityFeed.length === 0) {
        feedElement.innerHTML = '<div class="empty-state">No activity yet</div>';
        return;
      }

      feedElement.innerHTML = this.activityFeed.slice(0, 20).map(activity => {
        const icon = this.getActivityIcon(activity.type);
        const timeAgo = this.formatTimeAgo(activity.timestamp);

        return `
          <div class="activity-item">
            <div class="activity-icon">${icon}</div>
            <div class="activity-content">
              <div class="activity-user">${activity.user}</div>
              <div class="activity-details">${activity.details}</div>
              <div class="activity-time">${timeAgo}</div>
            </div>
          </div>
        `;
      }).join('');
    },

    getActivityIcon(type) {
      const icons = {
        'card_created': '➕',
        'card_updated': '✏️',
        'card_deleted': '🗑️',
        'comment_added': '💬',
        'tag_added': '🏷️',
        'mention': '@'
      };
      return icons[type] || '📌';
    },

    formatTimeAgo(timestamp) {
      const seconds = Math.floor((Date.now() - timestamp) / 1000);

      if (seconds < 60) return 'Just now';
      if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`;
      if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`;
      return `${Math.floor(seconds / 86400)}d ago`;
    },

    async addComment(ctx) {
      const commentInput = this.collaborationHub.querySelector('.comment-input');
      const text = commentInput.value.trim();

      if (!text) {
        ctx.utils.showToast('Comment cannot be empty', 'error');
        return;
      }

      const currentCardId = this.getCurrentCardId();
      if (!currentCardId) {
        ctx.utils.showToast('No card selected', 'error');
        return;
      }

      const comment = {
        id: this.generateId(),
        cardId: currentCardId,
        user: this.currentUser.username,
        text: text,
        timestamp: Date.now()
      };

      if (!this.comments[currentCardId]) {
        this.comments[currentCardId] = [];
      }

      this.comments[currentCardId].push(comment);

      // Check for mentions
      const mentions = text.match(/@(\w+)/g);
      if (mentions) {
        mentions.forEach(mention => {
          const username = mention.substring(1);
          if (!this.mentions[username]) {
            this.mentions[username] = [];
          }
          this.mentions[username].push({
            commentId: comment.id,
            cardId: currentCardId,
            text: text,
            timestamp: Date.now()
          });
        });
      }

      this.saveCollaborationData();
      this.addActivity('comment_added', currentCardId, `Commented on card`);

      commentInput.value = '';
      ctx.utils.showToast('Comment added', 'success');
      this.updateCommentsList(currentCardId);
      this.updateStats();
    },

    updateCommentsList(cardId) {
      const commentsList = this.collaborationHub.querySelector('.comments-list');
      if (!commentsList) return;

      const cardComments = this.comments[cardId] || [];

      if (cardComments.length === 0) {
        commentsList.innerHTML = '<div class="empty-state">No comments on this card yet</div>';
        return;
      }

      commentsList.innerHTML = cardComments.map(comment => `
        <div class="comment-item">
          <div class="comment-header">
            <span class="comment-user">👤 ${comment.user}</span>
            <span class="comment-time">${this.formatTimeAgo(comment.timestamp)}</span>
          </div>
          <div class="comment-text">${this.escapeHtml(comment.text)}</div>
        </div>
      `).join('');
    },

    updateShareLink() {
      const currentCardId = this.getCurrentCardId();
      const shareLink = this.collaborationHub.querySelector('.share-link');

      if (currentCardId && shareLink) {
        const url = new URL(window.location);
        url.searchParams.set('card', currentCardId);
        shareLink.value = url.toString();
      }
    },

    async copyShareLink(ctx) {
      const shareLink = this.collaborationHub.querySelector('.share-link');
      if (!shareLink || !shareLink.value) {
        ctx.utils.showToast('No card to share', 'error');
        return;
      }

      try {
        await navigator.clipboard.writeText(shareLink.value);
        ctx.utils.showToast('Link copied to clipboard!', 'success');
      } catch (err) {
        ctx.utils.showToast('Failed to copy link', 'error');
      }
    },

    shareViaEmail(ctx) {
      const currentCardId = this.getCurrentCardId();
      if (!currentCardId) {
        ctx.utils.showToast('No card to share', 'error');
        return;
      }

      const card = window.store?.cards[currentCardId];
      if (!card) return;

      const subject = encodeURIComponent(`CardSpoke: ${card.title}`);
      const body = encodeURIComponent(
        `Check out this card:\n\n${card.title}\n\n${card.body}\n\nView in CardSpoke: ${window.location.href}`
      );

      window.location.href = `mailto:?subject=${subject}&body=${body}`;
    },

    async shareAsJson(ctx) {
      const currentCardId = this.getCurrentCardId();
      if (!currentCardId) {
        ctx.utils.showToast('No card to share', 'error');
        return;
      }

      const card = window.store?.cards[currentCardId];
      if (!card) return;

      const exportData = {
        card: card,
        comments: this.comments[currentCardId] || [],
        exportedBy: this.currentUser.username,
        exportedAt: new Date().toISOString()
      };

      const json = JSON.stringify(exportData, null, 2);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `card-${currentCardId}.json`;
      a.click();
      URL.revokeObjectURL(url);

      ctx.utils.showToast('Card exported as JSON', 'success');
    },

    generateQRCode(ctx) {
      ctx.utils.showToast('QR Code generation requires external library - placeholder for now', 'info');
    },

    updateStats() {
      const totalComments = Object.values(this.comments).reduce((sum, comments) => sum + comments.length, 0);
      const activityCount = this.activityFeed.length;

      const totalCommentsEl = this.collaborationHub.querySelector('#total-comments');
      const activityCountEl = this.collaborationHub.querySelector('#activity-count');

      if (totalCommentsEl) totalCommentsEl.textContent = totalComments;
      if (activityCountEl) activityCountEl.textContent = activityCount;
    },

    getCurrentCardId() {
      const params = new URLSearchParams(window.location.search);
      return params.get('card') || null;
    },

    generateId() {
      return 'collab-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
    },

    escapeHtml(text) {
      const div = document.createElement('div');
      div.textContent = text;
      return div.innerHTML;
    },

    onCardSave(ctx, card, saveInfo) {
      if (saveInfo.isNew) {
        this.addActivity('card_created', card.id, `Created card "${card.title}"`);
      } else {
        this.addActivity('card_updated', card.id, `Updated card "${card.title}"`);
      }
    },

    onCardDelete(ctx, cardId) {
      this.addActivity('card_deleted', cardId, `Deleted a card`);

      // Clean up comments for deleted card
      delete this.comments[cardId];
      this.saveCollaborationData();
    },

    onCardRender(ctx, card, element) {
      // Add comment count badge
      const commentCount = (this.comments[card.id] || []).length;
      if (commentCount > 0) {
        const badge = document.createElement('span');
        badge.className = 'collab-comment-badge';
        badge.textContent = `💬 ${commentCount}`;
        badge.title = `${commentCount} comment${commentCount !== 1 ? 's' : ''}`;

        const titleElement = element.querySelector('.card-title');
        if (titleElement) {
          titleElement.appendChild(badge);
        }
      }
    },

    onNavigate(ctx, navigationInfo) {
      // Update comments list when navigating to a new card
      if (navigationInfo.cardId) {
        this.updateCommentsList(navigationInfo.cardId);
      }
    },

    onDisable(ctx) {
      if (this.collaborationHub && this.collaborationHub.parentNode) {
        this.collaborationHub.parentNode.removeChild(this.collaborationHub);
      }
      if (this.keyHandler) {
        document.removeEventListener('keydown', this.keyHandler);
      }
    },

    onUninstall(ctx) {
      if (confirm('Remove all collaboration data (comments, activity, etc.)?')) {
        localStorage.removeItem(this.STORAGE_KEY);
      }
    }
  });
})();

