#collaboration-hub {
  position: fixed;
  bottom: 20px;
  left: 20px;
  width: 380px;
  max-height: 600px;
  background: var(--bg-alt);
  border: 2px solid var(--border);
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
  z-index: 10000;
  display: flex;
  flex-direction: column;
}

#collaboration-hub.minimized .collab-hub-body {
  display: none;
}

.collab-hub-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  border-radius: 10px 10px 0 0;
  font-weight: bold;
}

.collab-user-badge {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  padding: 4px 10px;
  background: rgba(255, 255, 255, 0.2);
  border-radius: 12px;
  font-size: 0.85em;
}

.collab-hub-minimize {
  background: rgba(255, 255, 255, 0.2);
  border: none;
  color: white;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  cursor: pointer;
}

.collab-hub-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
}

.collab-tabs {
  display: flex;
  border-bottom: 2px solid var(--border);
}

.collab-tab {
  flex: 1;
  padding: 10px;
  background: var(--bg-alt);
  border: none;
  border-bottom: 3px solid transparent;
  cursor: pointer;
  font-size: 0.8em;
  transition: all 0.2s;
}

.collab-tab:hover {
  background: var(--bg-hover);
}

.collab-tab.active {
  border-bottom-color: var(--accent);
  background: var(--bg-primary);
}

.collab-tab-content {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
}

/* Activity Feed */
.activity-feed {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.activity-item {
  display: flex;
  gap: 12px;
  padding: 10px;
  background: var(--bg-hover);
  border-radius: 8px;
  border-left: 3px solid var(--accent);
}

.activity-icon {
  font-size: 1.2em;
}

.activity-content {
  flex: 1;
}

.activity-user {
  font-weight: bold;
  font-size: 0.9em;
}

.activity-details {
  font-size: 0.85em;
  color: var(--text-secondary);
  margin: 4px 0;
}

.activity-time {
  font-size: 0.75em;
  color: var(--text-secondary);
}

/* Comments */
.comments-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 16px;
}

.comment-item {
  padding: 10px;
  background: var(--bg-hover);
  border-radius: 8px;
}

.comment-header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 8px;
  font-size: 0.85em;
}

.comment-user {
  font-weight: bold;
}

.comment-time {
  color: var(--text-secondary);
}

.comment-text {
  font-size: 0.9em;
  line-height: 1.4;
}

.comment-composer {
  margin-top: auto;
  padding-top: 12px;
  border-top: 2px solid var(--border);
}

.comment-input {
  width: 100%;
  min-height: 60px;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-primary);
  color: var(--text-primary);
  resize: vertical;
  margin-bottom: 8px;
}

.add-comment-btn {
  width: 100%;
  padding: 8px;
  background: var(--accent);
  color: white;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-weight: bold;
}

.add-comment-btn:hover {
  opacity: 0.9;
}

/* Share */
.share-section h4 {
  margin: 0 0 12px 0;
}

.share-link-wrapper {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}

.share-link {
  flex: 1;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-primary);
  color: var(--text-primary);
}

.copy-link-btn {
  padding: 8px 12px;
  background: var(--accent);
  color: white;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}

.share-options {
  margin-bottom: 20px;
}

.share-options h5 {
  margin: 0 0 8px 0;
}

.share-buttons {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.share-buttons button {
  padding: 10px;
  background: var(--bg-hover);
  border: 1px solid var(--border);
  border-radius: 6px;
  cursor: pointer;
  text-align: left;
}

.share-buttons button:hover {
  background: var(--accent);
  color: white;
  border-color: var(--accent);
}

.collaboration-stats {
  padding: 12px;
  background: var(--bg-hover);
  border-radius: 8px;
}

.collaboration-stats h4 {
  margin: 0 0 8px 0;
}

.collaboration-stats > div {
  margin: 6px 0;
  font-size: 0.9em;
}

.collaboration-stats span {
  font-weight: bold;
  color: var(--accent);
}

/* Empty state */
.empty-state {
  padding: 20px;
  text-align: center;
  color: var(--text-secondary);
  font-style: italic;
}

/* Comment badge on cards */
.collab-comment-badge {
  display: inline-block;
  margin-left: 8px;
  padding: 2px 8px;
  background: #667eea;
  color: white;
  border-radius: 12px;
  font-size: 0.7em;
  font-weight: bold;
}
